// SliderArt.h -- the holster editor's slider art: three embedded textures, hse_sld_frame (128x16 teal rounded outline), hse_sld_wedge (128x16
// teal wedge, thin left to tall right, the vanilla Sound Options look) and hse_sld_mark (8x32 thin white double-arrow marker), registered
// through EmbedTex.h and handed out as pooled GUI image handles (same pattern as ResetIcon.h).
//
// Pixels live in ../_shared_src/SliderArtTex.inc (GENERATED by scripts/gen_slider_art.py). Usage: set embtex::g_log, call sliderArtEnsure()
// once while building the page (idempotent, Steam only), embtex::heal() every UI tick, then sliderArtFill(label, SA_Frame) etc. (or
// sliderArtApply for all three). sliderArtImage returns nullptr until the texture exists (a failed lookup is not pooled: it retries), and
// sliderArtFill then returns false so callers keep their plain fill. The slider parts are LABELS (no button path), so the fill call is
// guikit::setFill, the same second-path call resetIconApply uses for the label clone fallback. embtex::MaxTex (16) must hold this mod's
// other textures plus these 3 (and the 2 reset icons).
#pragma once
#include "EmbedTex.h"
#include "GuiKit.h"

namespace hse {

namespace sliderart_detail {
#include "SliderArtTex.inc"   // kSliderFrameTex, kSliderWedgeTex, kSliderMarkTex, kSliderTex[], kSliderTexCount
}

enum SliderArt { SA_Frame = 0, SA_Wedge = 1, SA_Mark = 2, SA_Count = 3 };

constexpr int kSliderWideW = 128, kSliderWideH = 16;   // frame and wedge source textures
constexpr int kSliderMarkW = 8, kSliderMarkH = 32;     // marker source texture (power-of-two height; 24 is not)

inline const embtex::Tex* sliderArtTextures() { return sliderart_detail::kSliderTex; }
inline int sliderArtTextureCount() { return static_cast<int>(sliderart_detail::kSliderTexCount); }
// Resref of one part; "" for an out-of-range value.
inline const char* sliderArtResref(int which) { return (which >= 0 && which < SA_Count) ? sliderart_detail::kSliderTex[which].resref : ""; }

// Create + fill + queue the three textures (EmbedTex ensure(): idempotent, Steam-only; false on any other exe or when an engine call fails).
inline bool sliderArtEnsure() { return embtex::ensure(sliderart_detail::kSliderTex, static_cast<int>(sliderart_detail::kSliderTexCount)); }

// Pooled GUI image handle of one part; nullptr until the texture exists (or for an out-of-range value). Never released.
inline void* sliderArtImage(int which) {
    static void* cache[SA_Count] = {};
    if (which < 0 || which >= SA_Count) return nullptr;
    if (!cache[which]) cache[which] = guikit::imageForRetry(sliderart_detail::kSliderTex[which].resref);
    return cache[which];
}

// Set one part as the fill of a LABEL control (guikit::setFill, optional rgb tint). False when the control is 0, the texture does not exist
// yet, or setFill refuses (border vtable gate); nothing is written in the first two cases.
inline bool sliderArtFill(uintptr_t label, int which, const float* tint = nullptr) {
    void* img = sliderArtImage(which);
    return label && img && guikit::setFill(label, img, tint);
}

// Apply frame / wedge / marker to their labels (a 0 control is skipped). Returns how many took (0..3); callers keep their plain fill for the rest.
inline int sliderArtApply(uintptr_t frame, uintptr_t wedge, uintptr_t mark) {
    const uintptr_t ctl[SA_Count] = { frame, wedge, mark };
    int n = 0;
    for (int i = 0; i < SA_Count; ++i) if (ctl[i] && sliderArtFill(ctl[i], i)) ++n;
    return n;
}

// Layout helpers (frac clamped to 0..1, NaN = 0): width of the wedge rect that reveals `frac` of a slider whose frame is frameW wide, and the
// left edge of the marker (markW wide) centred on that same position inside a frame starting at frameX.
inline float sliderClamp01(float f) { return (f > 0.0f) ? (f < 1.0f ? f : 1.0f) : 0.0f; }   // NaN fails f > 0 -> 0
inline float sliderWedgeWidth(float frameW, float frac) { return frameW * sliderClamp01(frac); }
inline float sliderMarkLeft(float frameX, float frameW, float frac, float markW = static_cast<float>(kSliderMarkW)) {
    return frameX + frameW * sliderClamp01(frac) - markW * 0.5f;
}

}  // namespace hse
